import React, { useEffect, useRef, useCallback, useId } from 'react';

export function Dialog({ open, onClose, title, children }) {
  const dialogRef = useRef(null);
  const backdropRef = useRef(null);
  const previouslyFocusedElement = useRef(null);
  const id = useId();
  const initialBodyOverflow = useRef(document.body.style.overflow);

  const focusFirstElement = useCallback(() => {
    const dialog = dialogRef.current;
    if (!dialog) return;

    const focusableSelectors = [
      'a[href]',
      'button:not([disabled])',
      'input:not([disabled]):not([type="hidden"])',
      'select:not([disabled])',
      'textarea:not([disabled])',
      '[tabindex]:not([tabindex="-1"])',
    ];
    const focusableElements = dialog.querySelectorAll(focusableSelectors.join(', '));
    const autofocusElement = dialog.querySelector('[data-autofocus]');

    if (autofocusElement) {
      autofocusElement.focus();
    } else if (focusableElements.length > 0) {
      focusableElements[0].focus();
    } else {
      dialog.focus();
    }
  }, []);

  useEffect(() => {
    if (open) {
      previouslyFocusedElement.current = document.activeElement;
      document.body.style.overflow = 'hidden';
      focusFirstElement();
    } else {
      if (previouslyFocusedElement.current && document.contains(previouslyFocusedElement.current) && previouslyFocusedElement.current !== document.body) {
        previouslyFocusedElement.current.focus();
      }
      document.body.style.overflow = initialBodyOverflow.current;
    }
  }, [open, focusFirstElement]);

  useEffect(() => {
    const handleKeyDown = (event) => {
      if (!open) return;

      if (event.key === 'Escape') {
        onClose();
      } else if (event.key === 'Tab') {
        const dialog = dialogRef.current;
        const focusableSelectors = [
          'a[href]',
          'button:not([disabled])',
          'input:not([disabled]):not([type="hidden"])',
          'select:not([disabled])',
          'textarea:not([disabled])',
          '[tabindex]:not([tabindex="-1"])',
        ];
        const focusableElements = dialog.querySelectorAll(focusableSelectors.join(', '));
        const firstElement = focusableElements[0];
        const lastElement = focusableElements[focusableElements.length - 1];

        if (focusableElements.length === 0) {
          event.preventDefault();
          dialog.focus();
        } else if (event.shiftKey && document.activeElement === firstElement) {
          event.preventDefault();
          lastElement.focus();
        } else if (!event.shiftKey && document.activeElement === lastElement) {
          event.preventDefault();
          firstElement.focus();
        }
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => {
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [open, onClose]);

  const handleBackdropClick = (event) => {
    if (event.target === backdropRef.current) {
      onClose();
    }
  };

  if (!open) return null;

  return (
    <div data-testid="backdrop" ref={backdropRef} onMouseDown={handleBackdropClick}>
      <div
        role="dialog"
        aria-modal="true"
        aria-labelledby={id}
        tabIndex={-1}
        ref={dialogRef}
      >
        <h2 id={id}>{title}</h2>
        {children}
      </div>
    </div>
  );
}
